import { useId, useState, type FormEvent } from 'react';
import { Alert, Button, Input, Select, Switch } from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function InviteTeammateForm() {
  const emailId = useId();
  const hintId = `${emailId}-hint`;
  const errorId = `${emailId}-error`;
  const roleId = useId();

  const [email, setEmail] = useState('');
  const [role, setRole] = useState('viewer');
  const [notify, setNotify] = useState(true);
  const [touched, setTouched] = useState(false);
  const [invited, setInvited] = useState<string | null>(null);

  const isValid = EMAIL_RE.test(email.trim());
  const showError = touched && !isValid;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
  }

  return (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-4)' }}>
      {invited && (
        <Alert
          tone="success"
          role="status"
          title="Приглашение отправлено"
          onClose={() => setInvited(null)}
          closeLabel="Закрыть сообщение"
        >
          Мы отправили приглашение на {invited}.
        </Alert>
      )}

      <form className="jx-stack" style={{ gap: 'var(--jx-space-4)' }} onSubmit={handleSubmit} noValidate>
        <div className="jx-field">
          <label className="jx-label" htmlFor={emailId}>
            Почта участника
          </label>
          <Input
            id={emailId}
            type="email"
            name="email"
            value={email}
            placeholder="name@company.com"
            invalid={showError}
            autoComplete="email"
            aria-describedby={showError ? `${hintId} ${errorId}` : hintId}
            onChange={(event) => setEmail(event.target.value)}
            onBlur={() => setTouched(true)}
          />
          <p className="jx-hint" id={hintId}>
            Приглашение придёт на рабочий адрес и будет действовать 7 дней.
          </p>
          {showError && (
            <p className="jx-error" id={errorId}>
              Введите адрес в формате name@company.com.
            </p>
          )}
        </div>

        <div className="jx-field">
          <label className="jx-label" htmlFor={roleId}>
            Роль в команде
          </label>
          <Select
            id={roleId}
            name="role"
            value={role}
            options={ROLES}
            onValueChange={setRole}
          />
        </div>

        <Switch
          checked={notify}
          onCheckedChange={setNotify}
          label="Отправить уведомление"
          description="Участник получит письмо сразу после создания приглашения."
        />

        <Button type="submit" variant="primary" disabled={!isValid}>
          Отправить приглашение
        </Button>
      </form>
    </div>
  );
}

